<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Campus; use Illuminate\Http\Request; use Illuminate\Validation\Rule;
class CampusController extends Controller {
public function places(){return view('admin.campuses.places',['campuses'=>Campus::where('is_active',true)->orderBy('name')->get(),'buildings'=>\App\Models\Building::with('campus')->withCount('locations')->orderBy('name')->paginate(20),'locations'=>\App\Models\Location::with('building.campus')->orderBy('name')->paginate(20,['*'],'locations_page')]);}
public function storeBuilding(Request $r){$d=$r->validate(['campus_id'=>'required|exists:campuses,id','name'=>'required|string|max:120','code'=>'required|string|max:32']);\App\Models\Building::create($d+['is_active'=>true]);return back()->with('status','Prédio cadastrado.');}
public function updateBuilding(Request $r,\App\Models\Building $building){$d=$r->validate(['name'=>'required|string|max:120','code'=>'required|string|max:32','is_active'=>'nullable|boolean']);$building->update($d+['is_active'=>$r->boolean('is_active')]);return back()->with('status','Prédio atualizado.');}
public function storeLocation(Request $r){$d=$r->validate(['building_id'=>'required|exists:buildings,id','name'=>'required|string|max:120','floor'=>'nullable|string|max:32','room'=>'nullable|string|max:32','details'=>'nullable|string|max:1000']);\App\Models\Location::create($d+['is_active'=>true]);return back()->with('status','Local cadastrado.');}
public function updateLocation(Request $r,\App\Models\Location $location){$d=$r->validate(['name'=>'required|string|max:120','floor'=>'nullable|string|max:32','room'=>'nullable|string|max:32','details'=>'nullable|string|max:1000','is_active'=>'nullable|boolean']);$location->update($d+['is_active'=>$r->boolean('is_active')]);return back()->with('status','Local atualizado.');}
public function index(){return view('admin.campuses.index',['campuses'=>Campus::withCount(['buildings','teams'])->orderBy('name')->paginate(20)]);}
public function create(){return view('admin.campuses.form',['campus'=>new Campus]);}
public function store(Request $r){$d=$r->validate(['name'=>'required|string|max:120','code'=>'required|string|max:32|unique:campuses,code','address'=>'nullable|string|max:255','city'=>'nullable|string|max:100','state'=>'nullable|string|max:2','timezone'=>'required|timezone','is_active'=>'nullable|boolean']);Campus::create($d+['is_active'=>$r->boolean('is_active')]);return redirect()->route('admin.campuses.index')->with('status','Campus criado.');}
public function edit(Campus $campus){return view('admin.campuses.form',compact('campus'));}
public function update(Request $r,Campus $campus){$d=$r->validate(['name'=>'required|string|max:120','code'=>['required','string','max:32',Rule::unique('campuses')->ignore($campus->id)],'address'=>'nullable|string|max:255','city'=>'nullable|string|max:100','state'=>'nullable|string|max:2','timezone'=>'required|timezone','is_active'=>'nullable|boolean']);$campus->update($d+['is_active'=>$r->boolean('is_active')]);return redirect()->route('admin.campuses.index')->with('status','Campus atualizado.');}
public function destroy(Campus $campus){abort_if($campus->tickets()->exists()||$campus->buildings()->exists(),409,'Campus vinculado a solicitações ou prédios; desative-o em vez de excluir.');$campus->delete();return back()->with('status','Campus removido.');}}
